-- 1. NẠP 8 VĂN BẢN QUY CHUẨN EVN
INSERT INTO evn_documents (id, doc_code, title, category, effective_date, summary, content) VALUES
('doc-01', 'QĐ-01/2025/ATĐ-EVN', 'Quy chuẩn An toàn điện & Xử lý Tình huống Khẩn cấp trên Lưới điện', 'An toàn điện', '2025-01-01', 'Quy định bắt buộc về khoảng cách an toàn, xử lý khi phát hiện sự cố đứt dây, đổ cột, cháy nổ thiết bị điện ngoài trời và trong nhà.', 'Quy chuẩn An toàn điện và Xử lý Khẩn cấp trên Lưới điện Quốc gia. Ban hành theo Quyết định số 01/2025/QĐ-ATĐ của Tập đoàn Điện lực. Điều 1: Khoảng cách an toàn phóng điện với đường dây cao thế và trung thế. Đối với đường dây 22kV, khoảng cách an toàn tối thiểu là 2.0 mét. Đối với đường dây 110kV là 4.0 mét, đường dây 220kV là 6.0 mét và 500kV là 8.0 mét. Điều 2: Xử lý khi phát hiện dây điện đứt rơi xuống đất hoặc vướng vào cây cối. Tuyệt đối không được đến gần trong phạm vi bán kính 10 mét tính từ điểm dây chạm đất. Giữ nguyên hiện trường, cảnh báo cho người xung quanh không lại gần. Gọi ngay số điện thoại khẩn cấp 19001909 hoặc 114 để lực lượng điều độ điện lực cắt điện khẩn cấp. Điều 3: Xử lý sự cố chập cháy thiết bị điện gia đình. Cần lập tức ngắt cầu dao tổng (Aptomat/CB). Dùng bình cứu hỏa khí CO2 hoặc bột chữa cháy chuyên dụng cho thiết bị điện. Tuyệt đối không dùng nước dập lửa khi chưa ngắt nguồn điện hoàn toàn. Điều 4: An toàn điện trong mùa mưa bão ngập lụt. Khi nước ngập đến sàn nhà hoặc mép ổ cắm, phải ngắt cầu dao nhánh và cầu dao tổng, không chạm tay ướt vào thiết bị điện.'),
('doc-02', 'QT-02/2024/SCD-EVN', 'Quy trình Tiếp nhận và Xử lý Báo Mất điện Khẩn cấp', 'Dịch vụ khách hàng', '2024-06-15', 'Quy trình 4 bước tiếp nhận phản ánh mất điện qua Tổng đài 19001909, App CSKH, Zalo OA và phân phối lệnh điều độ tự động.', 'Quy trình Tiếp nhận và Xử lý Báo Mất điện Khẩn cấp toàn hệ thống EVN. Bước 1: Tiếp nhận thông tin. Khách hàng thông báo mất điện qua hotline 19001909, App EVN CSKH hoặc Cổng Dịch vụ công Quốc gia. Cung cấp Mã khách hàng (PE...), địa chỉ và mô tả hiện tượng (mất điện toàn khu vực hay mất điện riêng gia đình, có tiếng nổ hay mùi khét không). Bước 2: Phân loại sự cố. Hệ thống tự động kiểm tra trạng thái trạm biến áp phân phối qua hệ thống SCADA. Nếu mất điện diện rộng do sự cố đường dây, hệ thống sẽ kích hoạt tin nhắn SMS thông báo dự kiến giờ có điện lại. Nếu mất điện đơn lẻ từng hộ, phiếu công tác sẽ tự động chuyển đến Đội Quản lý vận hành khu vực. Bước 3: Xuất quân xử lý. Đội sửa chữa lưu động có mặt tại hiện trường trong vòng tối đa 30 phút ở đô thị và 60 phút ở nông thôn. Bước 4: Nghiệm thu và phản hồi. Sau khi đóng điện, hệ thống gửi tin nhắn xác nhận hoàn thành đến số điện thoại khách hàng.'),
('doc-03', 'QĐ-03/2024/TG-EVN', 'Quy định Thời gian Khôi phục Cấp điện theo Cấp độ Sự cố', 'Điều độ vận hành', '2024-03-01', 'Thời gian tối đa để khôi phục điện phân theo 4 cấp độ: Sự cố nhẹ tại trạm, sự cố đứt dây hạ thế, sự cố máy biến áp, và thiên tai bão lũ.', 'Quy định chuẩn dịch vụ cấp điện EVN về Thời gian Khôi phục Điện. Cấp độ 1 (Sự cố nhánh hạ thế đơn lẻ, nhảy chì, cháy công tơ): Thời gian khôi phục tối đa không quá 02 giờ kể từ khi tiếp nhận thông tin. Cấp độ 2 (Sự cố nhảy Aptomat tổng trạm biến áp phân phối, đứt dây dẫn hạ thế lộ chính): Thời gian khôi phục tối đa không quá 04 giờ. Cấp độ 3 (Sự cố hỏng máy biến áp phân phối, gãy cột điện trung thế cần thay thế thiết bị): Thời gian khôi phục tối đa không quá 08 giờ trong điều kiện thời tiết bình thường. Cấp độ 4 (Sự cố thiên tai bất khả kháng như bão lớn, ngập lụt, sét đánh diện rộng): Ưu tiên khôi phục phụ tải quan trọng (bệnh viện, nhà máy nước sạch, cơ quan hành chính) trong 06 giờ; khu vực dân cư khôi phục từng phần trong vòng 24 đến 48 giờ sau khi nước rút hoặc bão tan.'),
('doc-04', 'QĐ-04/2024/BT-EVN', 'Quy định Cắt điện Bảo trì Định kỳ & Thủ tục Thông báo Kế hoạch', 'Bảo trì lưới điện', '2024-01-01', 'Thời hạn thông báo cắt điện kế hoạch tối thiểu 05 ngày trước thời điểm cắt, giới hạn số lần cắt điện trong năm và thời gian tối đa mỗi đợt.', 'Quy định Thông báo Cắt điện Kế hoạch phục vụ Sửa chữa, Bảo trì Lưới điện. Căn cứ Luật Điện lực và Thông tư 22/2020/TT-BCT của Bộ Công Thương. 1. Thời hạn thông báo: Điện lực có trách nhiệm thông báo cho khách hàng biết trước thời điểm cắt điện tối thiểu 05 ngày đối với khách hàng sinh hoạt và 07 ngày đối với khách hàng sản xuất kinh doanh lớn. 2. Hình thức thông báo: Đăng tải trên website CSKH, gửi tin nhắn SMS/Zalo OA đến số điện thoại đăng ký, và thông báo trên phương tiện truyền thanh địa phương. 3. Giới hạn thời gian cắt điện kế hoạch: Không cắt điện liên tục quá 10 giờ trong một ngày (từ 06h00 đến 18h00), không cắt điện vào ban đêm đối với phụ tải sinh hoạt dân cư trừ trường hợp khẩn cấp. Không cắt điện vào các ngày lễ lớn, kỳ thi tuyển sinh quốc gia, hoặc ngày có nhiệt độ dự báo thời tiết trên 36 độ C. 4. Tần suất: Không cắt điện bảo trì quá 02 lần/tháng đối với cùng một lộ đường dây.'),
('doc-05', 'QĐ-05/2024/BG-BCT', 'Biểu giá Bán lẻ Điện Sinh hoạt Bậc thang & Cách tính Lũy tiến', 'Giá điện & Hóa đơn', '2024-10-11', 'Biểu giá điện 6 bậc thang lũy tiến áp dụng toàn quốc (chưa gồm VAT 8%): Bậc 1 (0-50kWh): 1.893đ, Bậc 2 (51-100kWh): 1.956đ, Bậc 3 (101-200kWh): 2.271đ, Bậc 4 (201-300kWh): 2.860đ, Bậc 5 (301-400kWh): 3.197đ, Bậc 6 (từ 401kWh trở lên): 3.302đ.', 'Quyết định số 2699/QĐ-BCT về Biểu giá Bán lẻ Điện Sinh hoạt Bậc thang. Mức giá chưa bao gồm thuế giá trị gia tăng (VAT 8%). Bậc 1: Cho kWh từ 0 - 50 kWh: Đơn giá 1.893 đồng/kWh. Bậc 2: Cho kWh từ 51 - 100 kWh: Đơn giá 1.956 đồng/kWh. Bậc 3: Cho kWh từ 101 - 200 kWh: Đơn giá 2.271 đồng/kWh. Bậc 4: Cho kWh từ 201 - 300 kWh: Đơn giá 2.860 đồng/kWh. Bậc 5: Cho kWh từ 301 - 400 kWh: Đơn giá 3.197 đồng/kWh. Bậc 6: Cho kWh từ 401 kWh trở lên: Đơn giá 3.302 đồng/kWh. Phương pháp tính lũy tiến: Tiền điện = (Sản lượng từng bậc x Đơn giá bậc tương ứng) + Thuế VAT (8%). Hộ nghèo, hộ chính sách xã hội có lượng điện sử dụng không quá 50 kWh/tháng được hỗ trợ tiền điện tương đương 30 kWh tính theo giá bán lẻ điện bậc 1 (khoảng 56.790 đồng/hộ/tháng).'),
('doc-06', 'QĐ-06/2023/LĐ-EVN', 'Quy trình Lắp đặt Công tơ Mới & Di dời Điện kế Sinh hoạt', 'Thủ tục cấp điện', '2023-10-01', 'Thủ tục và hồ sơ cấp điện mới 1 pha, 3 pha sinh hoạt. Thời gian giải quyết tối đa 03 ngày làm việc, toàn bộ chi phí dây dẫn và công tơ do Điện lực chịu.', 'Quy trình Cấp điện Mới và Di dời Công tơ cho Khách hàng Sinh hoạt. 1. Hồ sơ đề nghị cấp điện mới gồm: Giấy đề nghị mua điện (theo mẫu EVN); Bản sao một trong các giấy tờ: Căn cước công dân gắn chip, Giấy chứng nhận quyền sử dụng đất, Hợp đồng mua bán nhà hoặc Hộ khẩu thường trú. 2. Thời gian giải quyết: Tối đa 03 ngày làm việc đối với khu vực đô thị và 05 ngày làm việc đối với khu vực nông thôn kể từ khi nhận đủ hồ sơ hợp lệ. 3. Chi phí: Ngành Điện chịu toàn bộ chi phí mua sắm công tơ, thiết bị đóng cắt, dây dẫn từ lưới điện hạ thế đến công tơ treo tại cột hoặc tường rào (chiều dài tối đa 30 mét). Khách hàng chỉ chịu chi phí dây dẫn và thiết bị điện từ sau công tơ vào trong nhà. 4. Di dời công tơ: Miễn phí nếu di dời do chỉnh trang đô thị hoặc nâng cấp lưới điện của Nhà nước. Nếu di dời theo yêu cầu riêng của khách hàng thì khách hàng thanh toán chi phí vật tư phát sinh.'),
('doc-07', 'QĐ-07/2024/BTTH-EVN', 'Chính sách Hỗ trợ & Bồi thường khi Mất điện Kéo dài', 'Quyền lợi khách hàng', '2024-05-01', 'Quy định mức hỗ trợ và bồi thường thiệt hại cho khách hàng khi sự cố mất điện kéo dài vượt quá thời gian cam kết tiêu chuẩn.', 'Chính sách Hỗ trợ và Bồi thường Khách hàng sử dụng điện khi gián đoạn cung cấp điện kéo dài. Căn cứ Hợp đồng Mua bán điện và Quy định tiêu chuẩn dịch vụ điện lực. 1. Điều kiện áp dụng: Khi mất điện do lỗi chủ quan của bên bán điện kéo dài liên tục trên 08 giờ mà không thông báo trước theo quy định, hoặc mất điện quá 24 giờ đối với sự cố thông thường. 2. Mức hỗ trợ đối với khách hàng sinh hoạt: Khấu trừ 10% tiền điện bậc 1 cho tháng xảy ra sự cố đối với các hộ bị mất điện liên tục từ 08 đến 16 giờ. Nếu mất điện liên tục trên 16 giờ đến 24 giờ, hỗ trợ chi phí sinh hoạt tương đương 150.000 đồng/hộ gia đình (trừ trực tiếp vào hóa đơn kỳ kế tiếp). Hỗ trợ cấp điện máy phát di động ưu tiên cho hộ gia đình có người bệnh thở oxy hoặc trẻ sơ sinh khi có yêu cầu khẩn cấp. 3. Bồi thường thiệt hại vật chất: Trường hợp điện áp tăng giảm đột ngột (quá áp, mất pha) do lỗi kỹ thuật của ngành điện làm cháy hỏng thiết bị điện gia dụng (tivi, tủ lạnh, máy giặt), ngành điện sẽ phối hợp đơn vị bảo hiểm giám định và bồi thường 100% chi phí sửa chữa hoặc thay thế tương đương trong vòng 07 ngày làm việc.'),
('doc-08', 'HD-08/2024/TKĐ-EVN', 'Hướng dẫn Tiết kiệm Điện & Quy trình Kiểm tra Hóa đơn Tăng Bất thường', 'Tiết kiệm điện', '2024-04-01', 'Giải pháp tiết kiệm điện máy lạnh, tủ lạnh trong mùa nắng nóng và quy trình yêu cầu phúc tra chỉ số công tơ khi hóa đơn tăng trên 30%.', 'Hướng dẫn Tiết kiệm Điện Hiệu quả và Thủ tục Khiếu nại Hóa đơn Tiền điện Tăng cao Mùa Nắng nóng. 1. Nguyên nhân hóa đơn tăng vọt mùa nắng nóng: Khi nhiệt độ môi trường ngoài trời tăng 1°C, mức tiêu thụ điện của máy lạnh tăng từ 2% đến 3,5%. Máy lạnh cài đặt ở 20°C tiêu tốn điện năng gấp 1,5 đến 2 lần so với cài đặt ở 26°C. 2. Khuyến nghị tiết kiệm điện: Cài đặt nhiệt độ điều hòa từ 26°C đến 28°C kết hợp quạt gió nhẹ; bảo dưỡng vệ sinh lưới lọc máy lạnh định kỳ 3 tháng/lần; rút phích cắm các thiết bị điện tử khi không sử dụng (tránh chế độ Standby tiêu hao 5-10% điện năng). 3. Quy trình yêu cầu kiểm tra phúc tra chỉ số công tơ: Khi hóa đơn tăng trên 30% so với tháng liền kề mà không rõ nguyên nhân, khách hàng gửi yêu cầu phúc tra trên App EVN CSKH hoặc gọi 19001909. Trong vòng 24 giờ, kỹ thuật viên Điện lực sẽ đến cùng khách hàng kiểm tra chỉ số tại cột, kiểm tra dòng rò dây dẫn sau công tơ và kiểm định sai số công tơ miễn phí. Nếu công tơ chạy sai quá giới hạn cho phép (±2%), ngành điện hoàn trả toàn bộ số tiền thu thừa và thay công tơ mới miễn phí.')
